fmt_only = [f for f, w in file_stats.items() if w]
substantive = [f for f, w in file_stats.items() if not w]
print('=== FORMATTING-ONLY ===')
for f in fmt_only: print(' ', f)
print()
print('=== SUBSTANTIVE ===')
for f in substantive: print(' ', f)
" 2>&1

